UPDATE Building_YieldChanges SET Yield=Yield+(SELECT Value FROM GARVEY_Config WHERE Name='OfficeCulture') WHERE BuildingType='BUILDING_GARVEY_PRINCIPALS_OFFICE' AND YieldType='YIELD_CULTURE';
UPDATE Building_YieldChanges SET Yield=Yield+(SELECT Value FROM GARVEY_Config WHERE Name='OfficeProduction') WHERE BuildingType='BUILDING_GARVEY_PRINCIPALS_OFFICE' AND YieldType='YIELD_PRODUCTION';
UPDATE Buildings SET MilitaryProductionModifier=(SELECT Value FROM GARVEY_Config WHERE Name='AaronMilitaryProduction') WHERE Type='BUILDING_GARVEY_AARON';
UPDATE Buildings SET MilitaryProductionModifier=(SELECT Value FROM GARVEY_Config WHERE Name='DetentionMilitaryProduction') WHERE Type='BUILDING_GARVEY_DETENTION';
UPDATE Buildings SET CultureRateModifier=(SELECT Value FROM GARVEY_Config WHERE Name='DeniseCulture') WHERE Type='BUILDING_GARVEY_DENISE';
UPDATE Buildings SET CultureRateModifier=(SELECT Value FROM GARVEY_Config WHERE Name='TimothyYield') WHERE Type='BUILDING_GARVEY_TIMOTHY';
